import { Request, Response, Router } from "express";
import { ListStockLevelsUseCase } from "../application/list-stock-levels-use-case";

export class StockController {
  constructor(private readonly listStockLevels: ListStockLevelsUseCase) {}

  routes(): Router {
    const router = Router();
    router.get("/", (req, res) => this.list(req, res));
    return router;
  }

  private async list(_req: Request, res: Response): Promise<void> {
    res.json(await this.listStockLevels.execute());
  }
}

